#include "motion/dsp/PathEngine.h"
#include <cmath>
#include <iostream>
#include <stdexcept>
int main(){try{const auto a=lsse::motion::PathEngine::orbit(0),b=lsse::motion::PathEngine::orbit(1),q=lsse::motion::PathEngine::orbit(0.25);if(std::abs(a.first-b.first)>1e-6||std::abs(a.second-b.second)>1e-6)throw std::runtime_error("orbit wrap failed");if(std::abs(q.first-1)>1e-5||std::abs(q.second)>1e-5)throw std::runtime_error("orbit geometry failed");for(int i=0;i<=100;++i){const auto g=lsse::motion::PathEngine::constantPowerPan(i/50.0f-1);if(std::abs(g.first*g.first+g.second*g.second-1)>1e-5)throw std::runtime_error("pan power changed");}for(int path=0;path<6;++path)for(int i=0;i<100;++i){const auto p=lsse::motion::PathEngine::position(path,i/100.0,77,.8f);if(!std::isfinite(p.first)||!std::isfinite(p.second)||std::abs(p.first)>1.001f||std::abs(p.second)>1.001f)throw std::runtime_error("path bounds failed");}if(lsse::motion::PathEngine::position(4,.42,77,.8f)!=lsse::motion::PathEngine::position(4,.42,77,.8f))throw std::runtime_error("random path was not deterministic");std::cout<<"MOTION path tests passed\n";return 0;}catch(const std::exception&x){std::cerr<<x.what()<<'\n';return 1;}}
